 "new_string": "def transform(grid):
    h, w = len(grid), len(grid[0])
    wall = next(r for r, row in enumerate(grid) if 2 in row)
    out = [row[:] for row in grid]
    # Each marker sends diagonal rays toward the barrier, which reflect and
    # continue upward as a symmetric pattern.
    for r, row in enumerate(grid[:wall]):
        for c, value in enumerate(row):
            if value == 4:
                # The ray is reflected at the barrier: retain the source and
                # fill the diagonal fan leading from the barrier to the source.
                depth = wall - r
                for d in range(1, depth + 1):
                    rr = r - d
                    if rr >= 0:
                        for cc in (c - d, c + d):
                            if 0 <= cc < w:
                                out[rr][cc] = 4
                # Fill the downward legs, stopping before the barrier.
                for d in range(1, depth):
                    rr = r + d
                    for cc in (c - d, c + d):
                        if 0 <= cc < w:
                            out[rr][cc] = 4
    return out
