 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    wall = next((r for r, row in enumerate(grid) if 2 in row), h)

    # Every 4 is part of a diagonal track. Extend each track in both
    # directions, staying on the same side of the horizontal divider.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 4:
                continue
            for dr, dc in ((-1, -1), (-1, 1), (1, -1), (1, 1)):
                d = 1
                while 0 <= r + dr*d < h and 0 <= c + dc*d < w:
                    rr = r + dr*d
                    cc = c + dc*d
                    if min(r, rr) <= wall <= max(r, rr):
                        break
                    out[rr][cc] = 4
                    d += 1
    return out

