    h, w = len(grid), len(grid[0])
    wall = next((r for r, row in enumerate(grid) if 2 in row), h)
    out = [row[:] for row in grid]
    seeds = [(r, c) for r in range(wall) for c in range(w) if grid[r][c] == 4]

    # Above the divider, each marker advances toward it. At distance two,
    # the trajectory fans sideways one cell and back diagonally above.
    for r, c in seeds:
        out[r][c] = 0
        distance = wall - r
        if distance == 2:
            if r + 1 < wall:
