            for cc in (c-2, c+2):
                if 0 <= cc < w and r-1 >= 0:
                    out[r-1][cc] = 4
        else:
            if r + 1 < wall:
                out[r+1][c] = 4

    # A below-divider seed is unchanged.
    return out

